import sys
from collections import defaultdict, deque

def bellman_ford(graph, start, n):
    dist = [float('inf')] * (n + 1)
    dist[start] = 0

    for _ in range(n - 1):
        for u in range(1, n + 1):
            if dist[u] == float('inf'):
                continue
            for v, weight in graph[u]:
                dist[v] = min(dist[v], dist[u] + weight)

    return dist

def find_largest_fee(N, P, X, Y, partnerships, M, swerc_banks):
    graph = defaultdict(list)

    for a, b, c in partnerships:
        graph[a].append((b, c))
        graph[b].append((a, c))

    # Find the shortest path from X to Y without considering SWERC's fees
    dist = bellman_ford(graph, X, N)

    if dist[Y] == float('inf'):
        return "Impossible"

    # Check if increasing the fee between any two banks connected through SWERC's network can make the path cheaper
    for u in swerc_banks:
        for v in swerc_banks:
            if u != v and (u, v) in graph or (v, u) in graph:
                for w, _ in graph[u]:
                    if w != v and (w, v) in graph or (v, w) in graph:
                        for x, _ in graph[v]:
                            if x != u and (x, u) in graph or (u, x) in graph:
                                new_dist = dist[u] + dist[v] + dist[w] + dist[x]
                                if new_dist < dist[Y]:
                                    return "Infinity"

    return "Impossible"

if __name__ == "__main__":
    input = sys.stdin.read
    data = input().split()

    index = 0
    N = int(data[index])
    P = int(data[index + 1])
    X = int(data[index + 2])
    Y = int(data[index + 3])
    index += 4

    partnerships = []
    for _ in range(P):
        a = int(data[index])
        b = int(data[index + 1])
        c = int(data[index + 2])
        partnerships.append((a, b, c))
        index += 3

    M = int(data[index])
    swerc_banks = list(map(int, data[index + 1:index + M + 1]))

    result = find_largest_fee(N, P, X, Y, partnerships, M, swerc_banks)
    print(result)
